"""Generate the salary page's small 4-bpp CJK subset from an OFL Noto font."""
import argparse
from pathlib import Path
from PIL import Image, ImageDraw, ImageFont

parser = argparse.ArgumentParser(description=__doc__)
parser.add_argument('font', type=Path)
args = parser.parse_args()
root = Path(__file__).resolve().parent.parent
chars = sorted({c for c in (root / 'main/salary_ui.c').read_text(encoding='utf-8') if ord(c) > 127})
font = ImageFont.truetype(str(args.font), 16)
lines = ['// Noto Sans SC subset. Adobe copyright; SIL OFL 1.1: assets/salary_cat/OFL.txt.',
         '// Generated by tools/generate_salary_font.py.', '#include "lvgl.h"', '#include <stdint.h>',
         'static const uint32_t codepoints[] = {' + ','.join(hex(ord(c)) for c in chars) + '};',
         'static const uint8_t bitmaps[][152] = {']
for char in chars:
    image = Image.new('L', (16, 19))
    ImageDraw.Draw(image).text((0, 16), char, font=font, fill=255, anchor='ls')
    pixels = list(image.getdata())
    data = [(pixels[i] >> 4) << 4 | (pixels[i + 1] >> 4) for i in range(0, len(pixels), 2)]
    lines.append('    {' + ','.join(hex(v) for v in data) + '},')
lines += ['};', '''
static int find_glyph(uint32_t letter)
{
    for (unsigned i = 0; i < sizeof(codepoints) / sizeof(codepoints[0]); ++i)
        if (codepoints[i] == letter) return i;
    return -1;
}
static bool glyph(const lv_font_t *font, lv_font_glyph_dsc_t *out, uint32_t letter, uint32_t next)
{
    (void)font;
    if (letter < 128) return lv_font_montserrat_16.get_glyph_dsc(&lv_font_montserrat_16, out, letter, next);
    if (find_glyph(letter) < 0) return false;
    *out = (lv_font_glyph_dsc_t){.adv_w = 16, .box_w = 16, .box_h = 19, .ofs_y = -3, .bpp = 4};
    return true;
}
static const uint8_t *bitmap(const lv_font_t *font, uint32_t letter)
{
    (void)font;
    if (letter < 128) return lv_font_montserrat_16.get_glyph_bitmap(&lv_font_montserrat_16, letter);
    int index = find_glyph(letter);
    return index < 0 ? NULL : bitmaps[index];
}
const lv_font_t font_salary16 = {
    .get_glyph_dsc = glyph, .get_glyph_bitmap = bitmap, .line_height = 19, .base_line = 3,
};
''']
(root / 'main/font_salary16.c').write_text('\n'.join(lines), encoding='utf-8')
print(f'Generated {len(chars)} CJK glyphs; {len(chars) * 152} bitmap bytes.')
